* {
    font-family: 'Cabin';
    font-style: normal;
    font-weight: 700;
    font-size: 32px;
    line-height: 39px;
    /* identical to box height */

    display: flex;
    align-items: center;

    /* Text/text--primary-actionable */

    color: #FFFFFF;


    /* Inside auto layout */

    flex: none;
    order: 0;
    flex-grow: 0;
}

* {
    /* Text/md */

    font-family: 'Lato';
    font-style: normal;
    font-weight: 400;
    font-size: 16px;
    line-height: 19px;

    /* Neutral/neutral-2 */

    color: #E4E6EA;


    /* Inside auto layout */

    flex: none;
    order: 1;
    flex-grow: 0;
}

